#include <iostream>
#include <climits>
#include <stdint.h>
int main() {
  int16_t a = INT16_MAX; //Max value for a 16-bit signed int
  int32_t b = a;       //Implicit conversion to 32-bit
  uint16_t c = INT16_MAX;  //Implicit conversion to unsigned 16-bit
  int32_t d = c;     //Implicit conversion to 32-bit
  std::cout << "a: " << a << std::endl;
  std::cout << "b: " << b << std::endl;
  std::cout << "c: " << c << std::endl;
  std::cout << "d: " << d << std::endl;
  return 0;
}
